module top_module_tb;

    // Testbench signals (sequential circuit)
    reg async_input;
    reg clk;
    reg reset;
    wire sync_output;

    // Test tracking
    integer test_num;
    integer pass_count;
    integer fail_count;

    // Instantiate the DUT (Device Under Test)
    top_module dut (
        .async_input(async_input),
        .clk(clk),
        .reset(reset),
        .sync_output(sync_output)
    );

    // Clock generation (10ns period)
    initial begin
        clk = 0;
        forever #5 clk = ~clk;
    end

        task reset_dut;

        begin
            @(negedge clk);
            reset = 1;
            async_input = 0;
            @(negedge clk);
            reset = 0;
            @(negedge clk);
        end
        endtask
    task testcase001;

        begin
            test_num = test_num + 1;
            $display("Testcase %0d: Reset behavior", test_num);
            reset_dut();

            #1;


            check_outputs(1'b0);
        end
        endtask

    task testcase002;

        begin
            test_num = test_num + 1;
            $display("Testcase %0d: Synchronize HIGH input", test_num);
            reset_dut();

            async_input = 1;

            @(posedge clk);
            @(posedge clk);
            #1;

            #1;


            check_outputs(1'b1);
        end
        endtask

    task testcase003;

        begin
            test_num = test_num + 1;
            $display("Testcase %0d: Synchronize LOW input after HIGH", test_num);
            reset_dut();


            async_input = 1;
            repeat(2) @(posedge clk);


            async_input = 0;
            repeat(2) @(posedge clk);
            #1;

            #1;


            check_outputs(1'b0);
        end
        endtask

    task testcase004;

        begin
            test_num = test_num + 1;
            $display("Testcase %0d: Stability check (input toggle between edges)", test_num);
            reset_dut();

            async_input = 1;
            @(posedge clk);
            #2;
            async_input = 0;
            #2;
            async_input = 1;

            @(posedge clk);
            #1;



            #1;




            check_outputs(1'b1);
        end
        endtask

    task testcase005;

        begin
            test_num = test_num + 1;
            $display("Testcase %0d: Reset mid-operation", test_num);
            reset_dut();

            async_input = 1;
            @(posedge clk);

            reset = 1;
            @(posedge clk);
            #1;


            #1;



            check_outputs(1'b0);
            reset = 0;
        end
        endtask

